from mpmath import mp, mpf, sqrt, nint, eye, matrix
from math import gcd

mp.dps = 200

def pslq(x, tol=None, maxiter=100000):
    n = len(x)
    if tol is None:
        tol = mpf(10) ** (-(mp.dps - 20))
    # tail sums s_k^2 = sum_{i>=k} x_i^2
    s = [mpf(0)] * (n + 1)
    for k in range(n - 1, -1, -1):
        s[k] = sqrt(s[k + 1] ** 2 + x[k] ** 2)
    t = s[0]
    y = [x[k] / t for k in range(n)]
    sn = [s[k] / t for k in range(n + 1)]

    # H: n x (n-1)
    H = matrix(n, n - 1)
    for j in range(n - 1):
        H[j, j] = sn[j + 1] / sn[j]
        for i in range(j + 1, n):
            H[i, j] = -y[i] * y[j] / (sn[j] * sn[j + 1])

    A = eye(n)
    B = eye(n)

    def reduce_H():
        for i in range(1, n):
            for j in range(min(i, n - 1) - 1, -1, -1):
                if H[j, j] == 0:
                    continue
                tq = nint(H[i, j] / H[j, j])
                if tq == 0:
                    continue
                y[j] = y[j] + tq * y[i]
                for k in range(j + 1):
                    H[i, k] = H[i, k] - tq * H[j, k]
                for k in range(n):
                    A[i, k] = A[i, k] - tq * A[j, k]
                    B[k, j] = B[k, j] + tq * B[k, i]

    reduce_H()

    gamma = sqrt(mpf(4) / 3)
    for it in range(maxiter):
        best = None; r = 0
        for i in range(n - 1):
            v = gamma ** i * abs(H[i, i])
            if best is None or v > best:
                best = v; r = i
        # swap rows r, r+1
        y[r], y[r + 1] = y[r + 1], y[r]
        for k in range(n - 1):
            H[r, k], H[r + 1, k] = H[r + 1, k], H[r, k]
        for k in range(n):
            A[r, k], A[r + 1, k] = A[r + 1, k], A[r, k]
            B[k, r], B[k, r + 1] = B[k, r + 1], B[k, r]
        # corner reduction
        if r < n - 1:
            t0 = sqrt(H[r, r] ** 2 + H[r + 1, r] ** 2)
            if t0 != 0:
                t1 = H[r, r] / t0
                t2 = H[r + 1, r] / t0
                for i in range(r, n):
                    t3 = H[i, r]
                    t4 = H[i, r + 1] if r + 1 < n - 1 else mpf(0)
                    H[i, r] = t1 * t3 + t2 * t4
                    if r + 1 < n - 1:
                        H[i, r + 1] = t1 * t4 - t2 * t3
        reduce_H()
        idx = min(range(n), key=lambda i: abs(y[i]))
        if abs(y[idx]) < tol:
            return [int(B[i, idx]) for i in range(n)]
    idx = min(range(n), key=lambda i: abs(y[i]))
    return [int(B[i, idx]) for i in range(n)]

def main():
    import sys
    sys.path.insert(0, '/app')
    from constants import get_constants
    x = get_constants()
    rel = pslq(x)
    g = 0
    for a in rel:
        g = gcd(g, abs(a))
    if g > 1:
        rel = [a // g for a in rel]
    for a in rel:
        if a != 0:
            if a < 0:
                rel = [-v for v in rel]
            break
    resid = sum(mpf(a) * xi for a, xi in zip(rel, x))
    print("relation:", rel)
    print("residual:", mp.nstr(resid, 20))
    with open('/app/relation.txt', 'w') as f:
        for a in rel:
            f.write("%d\n" % a)

if __name__ == '__main__':
    main()
